import{_ as s,C as n,o as a,c as i,a2 as e,E as r}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Checkout Deals","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/checkout-deals.md","filePath":"marketing/checkout-deals.md","lastUpdated":1789411447000}'),l={name:"marketing/checkout-deals.md"};function d(g,t,c,h,u,p){const o=n("ImagePopup");return a(),i("div",null,[t[0]||(t[0]=e('<h1 id="checkout-deals" tabindex="-1">Checkout Deals <a class="header-anchor" href="#checkout-deals" aria-label="Permalink to &quot;Checkout Deals&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>A checkout deal is a discount on the cart. It can apply automatically, or only when the customer enters a coupon code. Use it for offers such as 10% off when a customer spends a certain amount, or buy two and get one free.</p><div class="info custom-block"><p class="custom-block-title">In a cart with several sellers</p><p>A customer&#39;s cart can hold products from many sellers:</p><ul><li>A seller&#39;s deal only discounts that seller&#39;s products in the cart, including catalog products the seller sells.</li><li>Conditions such as <strong>Subtotal</strong> count only that seller&#39;s products.</li><li>Sellers can&#39;t offer free shipping or shipping discounts.</li><li>The store&#39;s own cart rules don&#39;t discount seller products.</li></ul></div><h2 id="create-a-checkout-deal" tabindex="-1">Create a checkout deal <a class="header-anchor" href="#create-a-checkout-deal" aria-label="Permalink to &quot;Create a checkout deal&quot;">​</a></h2><ol><li>Go to <strong>Marketing &gt;&gt; Checkout Deals</strong>.</li><li>Click <strong>Create Checkout Deal</strong>.</li><li>Fill in the <strong>Deal</strong>, <strong>Details</strong> and <strong>Advanced</strong> tabs, described below.</li><li>Click <strong>Save Checkout Deal</strong>.</li></ol><p>You&#39;ll see <strong>Checkout deal created successfully.</strong></p><h3 id="deal" tabindex="-1">Deal <a class="header-anchor" href="#deal" aria-label="Permalink to &quot;Deal&quot;">​</a></h3>',8)),r(o,{src:"/images/checkout-deals/deal.png",alt:"The Deal tab with the four kinds of deal"}),t[1]||(t[1]=e('<p>Under <strong>How would you like to reward your shoppers?</strong>, choose a kind of deal and fill in its amounts:</p><table tabindex="0"><thead><tr><th>Deal</th><th>What it does</th><th>Fields</th></tr></thead><tbody><tr><td><strong>Percentage off the order</strong></td><td>A percentage off your matching products in the cart</td><td><strong>Discount Percent (%)</strong>, <strong>Maximum Discounted Quantity</strong></td></tr><tr><td><strong>Fixed amount off the order</strong></td><td>A set amount off the cart, once per order</td><td><strong>Discount Amount</strong></td></tr><tr><td><strong>Fixed amount off each item</strong></td><td>A set amount off each matching product</td><td><strong>Discount Amount</strong>, <strong>Maximum Discounted Quantity</strong></td></tr><tr><td><strong>Buy X, get Y free</strong></td><td>Free units of a product when the customer buys a set quantity of it</td><td><strong>Free Quantity</strong>, <strong>Buy X Quantity</strong>, <strong>Maximum Eligible Quantity</strong></td></tr></tbody></table><p>For <strong>Buy X, get Y free</strong>, the free units are of the same product, and the customer adds them to the cart. With <strong>Buy X Quantity</strong> 2 and <strong>Free Quantity</strong> 1, the third unit is free. There is no discount when <strong>Free Quantity</strong> is more than <strong>Buy X Quantity</strong>, or when <strong>Buy X Quantity</strong> is 0.</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3>',4)),r(o,{src:"/images/checkout-deals/details.png",alt:"The Details tab with a coupon code"}),t[2]||(t[2]=e('<ol><li>Under <strong>What should this deal be called?</strong>, enter a <strong>Name</strong> and, if you like, a <strong>Description</strong>.</li><li>Under <strong>How do shoppers get this deal?</strong>, choose the <strong>Coupon Type</strong>: <ul><li><strong>No Coupon</strong> applies the deal automatically.</li><li><strong>Specific Coupon</strong> needs a code at checkout.</li></ul></li><li>For a specific coupon, choose <strong>Auto Generate Coupon</strong>: <ul><li><strong>No</strong> to enter one <strong>Coupon Code</strong> yourself. Codes must be unique across the store.</li><li><strong>Yes</strong> to create many codes after you save. See <a href="#create-coupon-codes">Create coupon codes</a>.</li></ul></li><li>For a specific coupon, enter <strong>Total Uses</strong> to limit how many times each coupon code can be used, including each generated code. Leave it at 0 for no limit.</li><li>Under <strong>When should it run?</strong>, choose the <strong>Starts From</strong> and <strong>Ends Till</strong> dates. The deal stops at the start of its <strong>Ends Till</strong> date, so choose the day after the last day you want it to run.</li></ol><h3 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h3>',2)),r(o,{src:"/images/checkout-deals/advanced.png",alt:"The Advanced tab with cart conditions"}),t[3]||(t[3]=e('<p>Add conditions in the same way as for a product discount. Checkout deals can also check the cart:</p><ul><li><strong>Cart attribute</strong> — <strong>Subtotal</strong>, <strong>Total items-qty</strong>, <strong>Payment method</strong>, <strong>Shipping method</strong>, <strong>Shipping postcode</strong>, <strong>Shipping state</strong>, <strong>Shipping country</strong>.</li><li><strong>Cart item attribute</strong> — <strong>Price in cart</strong>, <strong>Quantity in cart</strong>, <strong>Total Weight</strong>, <strong>Subtotal</strong>, <strong>Additional</strong>.</li><li><strong>Product attribute</strong> — <strong>Categories</strong>, <strong>Categories(Children Only)</strong>, <strong>Categories(Parent Only)</strong>, <strong>Attribute Family</strong> and product attributes. Each product attribute can also be checked on child products only or parent products only.</li></ul><p>Under <strong>Who should it apply to?</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Channels</strong></td><td>The channels the deal runs on</td></tr><tr><td><strong>Customer Groups</strong></td><td>The customer groups who get the deal</td></tr><tr><td><strong>Priority</strong></td><td>The order your deals are applied in, starting from the lowest number</td></tr><tr><td><strong>Stop Further Rules</strong></td><td>Choose <strong>Yes</strong> to stop your deals with a higher priority number from applying once this one does</td></tr><tr><td><strong>Uses Per Customer</strong></td><td>How many times one signed-in customer can use the deal. Guests aren&#39;t limited. Leave it at 0 for no limit.</td></tr><tr><td><strong>Status</strong></td><td>Switches the deal on or off</td></tr></tbody></table><p>When several of your deals match, they all apply, in priority order, until a deal with <strong>Stop Further Rules</strong> set to <strong>Yes</strong>. A cart can hold only one coupon code at a time.</p><h2 id="create-coupon-codes" tabindex="-1">Create coupon codes <a class="header-anchor" href="#create-coupon-codes" aria-label="Permalink to &quot;Create coupon codes&quot;">​</a></h2><ol><li>Create a deal with <strong>Specific Coupon</strong> and <strong>Auto Generate Coupon</strong> set to <strong>Yes</strong>, and save it.</li><li>In <strong>Marketing &gt;&gt; Checkout Deals</strong>, click the edit icon on the deal.</li><li>Open the <strong>Details</strong> tab and click <strong>Generate now</strong>.</li><li>In <strong>Generate Coupons</strong>, enter the <strong>Coupon Quantity</strong>, from 1 to 1,000, and the <strong>Coupon Length</strong>, from 10 to 100 characters.</li><li>Choose the <strong>Code Format</strong>: <strong>Alphanumeric</strong>, <strong>Alphabetical</strong> or <strong>Numeric</strong>.</li><li>If you like, enter a <strong>Code Prefix</strong> and <strong>Code Suffix</strong>.</li><li>Click <strong>Generate</strong>.</li></ol>',7)),r(o,{src:"/images/checkout-deals/generate-coupons.png",alt:"The Generate Coupons dialog"}),t[4]||(t[4]=e('<p>The page reloads, and the codes are listed on the same tab with their <strong>Times Used</strong>, <strong>Created Date</strong> and <strong>Expiration Date</strong>. Click the delete icon to remove a code.</p><h2 id="copy-a-deal" tabindex="-1">Copy a deal <a class="header-anchor" href="#copy-a-deal" aria-label="Permalink to &quot;Copy a deal&quot;">​</a></h2><p>Click the copy icon on a deal&#39;s row. A copy named <strong>Copy of …</strong> is created straight away, switched off, and opens for editing. Coupon codes aren&#39;t copied, so add a new code or generate new ones.</p><h2 id="manage-your-deals" tabindex="-1">Manage your deals <a class="header-anchor" href="#manage-your-deals" aria-label="Permalink to &quot;Manage your deals&quot;">​</a></h2><p>The <strong>Checkout Deals</strong> list shows each deal&#39;s name, whether it is active, its priority and its dates, with icons to edit, copy or delete it.</p><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Checkout Deals</strong> to see the deals sellers have created, with the <strong>Seller</strong>, status, priority and dates. You can filter the list by status. To delete a seller&#39;s deal, click its delete icon, or tick several deals and use <strong>Select Action &gt;&gt; Delete</strong>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>Checkout Deals</strong>, with <strong>Create</strong>, <strong>Edit</strong>, <strong>Copy</strong>, <strong>Delete</strong> and <strong>Coupons</strong> as needed.</li><li>Admins need <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Checkout Deals</strong> with <strong>Delete</strong> to delete sellers&#39; deals.</li></ul>',9))])}const y=s(l,[["render",d]]);export{f as __pageData,y as default};
